style.css:
@-moz-document url-prefix("chrome://newtab") {
/* Mantener fondo personalizado de Chrome */
body {
    background: transparent !important;
}

/* Variables del tema */
ntp-app {

    /* Barra de búsqueda translúcida */
    --color-new-tab-page-realbox-background:
        rgba(255,255,255,.14) !important;

    --color-new-tab-page-realbox-background-hovered:
        rgba(255,255,255,.18) !important;

    --color-new-tab-page-realbox-foreground:
        white !important;

    /* Accesos directos */
    --color-new-tab-page-most-visited-foreground:
        white !important;

    /* Ocultar elementos decorativos */
    --color-new-tab-page-logo-foreground:
        transparent !important;
}

/* Efecto vidrio */
ntp-app {
    backdrop-filter: blur(0px);
}

/* Centrado general */
body {
    display: flex;
    justify-content: center;
    align-items: center;
}
}
